using Rynzo.Client.Features.Crm.Models;
using Rynzo.Client.Utilities;
using System.Globalization;
using System.Text.RegularExpressions;
namespace Rynzo.Client.Features.Crm.Services;

public sealed class CrmCompaniesState
{
    public CrmCompaniesSource Data { get; } = CrmCompaniesSource.Load(); public List<CrmCompany> Companies { get; }
    public List<long> Selected { get; } = []; public CrmCompany? Active { get; set; }
    public CompanyDraft Draft { get; set; } = new(); public string Query { get; set; } = ""; public string[] Filters { get; } = ["All industries", "All sizes", "All revenue", "All statuses", "All owners", "All regions", "All tags", "Any activity", "Recently Added"]; public string Text { get; set; } = ""; public string BulkValue { get; set; } = "Sophia Carter"; public int PageSize { get; set; } = 20;
    public CrmCompaniesState() { Companies = [.. Data.Companies]; Draft = Data.Blank with { }; }
    public CrmCompany[] Filtered { get { var rows = Companies.Where(c => string.Join(' ', new[] { c.Name, c.Domain, c.Industry, c.Country, c.Owner }.Concat(c.Tags)).Contains(Query, StringComparison.OrdinalIgnoreCase) && (Filters[0] == "All industries" || c.Industry == Filters[0]) && (Filters[1] == "All sizes" || c.Size == Filters[1]) && (Filters[2] switch { "Under $1M" => c.Revenue < 1e6, "$1M-$10M" => c.Revenue >= 1e6 && c.Revenue <= 1e7, "$10M-$50M" => c.Revenue > 1e7 && c.Revenue <= 5e7, "$50M-$100M" => c.Revenue > 5e7 && c.Revenue <= 1e8, "$100M+" => c.Revenue > 1e8, _ => true }) && (Filters[3] == "All statuses" || c.Status == Filters[3]) && (Filters[4] == "All owners" || c.Owner == Filters[4]) && (Filters[5] == "All regions" || c.Country == Filters[5]) && (Filters[6] == "All tags" || c.Tags.Contains(Filters[6])) && (Filters[7] switch { "Today" => c.Days == 0, "Last 7 Days" => (c.Days ?? 99) <= 7, "Last 30 Days" => (c.Days ?? 99) <= 30, "No Activity" => c.Days is null, "Overdue Follow-up" => c.FollowUp == "Overdue", _ => true })); return (Filters[8] switch { "Company A-Z" => rows.OrderBy(c => c.Name, StringComparer.Create(CultureInfo.GetCultureInfo("en-US"), false)), "Highest Revenue" => rows.OrderByDescending(c => c.Revenue), "Largest Company" => rows.OrderByDescending(c => c.SizeStart), "Highest Pipeline Value" => rows.OrderByDescending(c => c.Pipeline), "Most Contacts" => rows.OrderByDescending(c => c.Contacts), "Last Activity" => rows.OrderBy(c => c.Days ?? 99), _ => rows.OrderByDescending(c => c.Id) }).ToArray(); } }
    public CrmCompany[] Visible => Filtered.Take(PageSize).ToArray(); public bool AllSelected => Visible.Length > 0 && Visible.All(c => Selected.Contains(c.Id));
    public void Reset() { Query = ""; for (var i = 0; i < Filters.Length; i++) Filters[i] = Data.Filters[i][0]; }
    public void Toggle(long id) { if (!Selected.Remove(id)) Selected.Add(id); }
    public void SelectAll() { var clear = AllSelected; Selected.Clear(); if (!clear) Selected.AddRange(Visible.Select(c => c.Id)); }
    public void BeginAdd() => Draft = Data.Blank with { };
    public void BeginEdit(CrmCompany c) { Active = c; Draft = new() { Name = c.Name, Domain = c.Domain, Industry = c.Industry, Size = c.Size, Revenue = c.Revenue.ToString(CultureInfo.InvariantCulture), Status = c.Status, Owner = c.Owner, Country = c.Country, Tags = string.Join(", ", c.Tags), Notes = string.Join(' ', c.Notes) }; }
    public void Update(long id, Func<CrmCompany, CrmCompany> patch) { for (var i = 0; i < Companies.Count; i++) if (Companies[i].Id == id) Companies[i] = patch(Companies[i]); if (Active?.Id == id) Active = patch(Active); }
    public void Bulk(Func<CrmCompany, CrmCompany> patch) { for (var i = 0; i < Companies.Count; i++) if (Selected.Contains(Companies[i].Id)) Companies[i] = patch(Companies[i]); }
    public bool Save(bool add) { var revenue = JavaScriptNumber.Parse(Draft.Revenue); if (Draft.Name.Length == 0 || Draft.Domain.Length > 0 && !Regex.IsMatch(Draft.Domain, @"^\S+\.\S+$") || revenue < 0) return false; CrmCompany Patch(CrmCompany c) => c with { Name = Draft.Name, Domain = Draft.Domain, Industry = Draft.Industry, Size = Draft.Size, Revenue = revenue, Status = Draft.Status, Owner = Draft.Owner, Country = Draft.Country, Tags = Draft.Tags.Split(',').Select(t => t.Trim()).Where(t => t.Length > 0).ToArray(), Notes = Draft.Notes.Length > 0 ? [Draft.Notes] : [] }; if (add) { var initials = string.Concat(Draft.Name.Split(' ').Select(s => s.Length > 0 ? s[..1] : "")); Companies.Add(Patch(new() { Id = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(), Initials = initials[..Math.Min(2, initials.Length)].ToUpperInvariant() })); } else if (Active is not null) Update(Active.Id, Patch); return true; }
    public bool Confirm(string mode) { if (mode == "bulkOwner") Bulk(c => c with { Owner = BulkValue }); else if (mode == "bulkStatus") Bulk(c => c with { Status = BulkValue }); else if (mode == "bulkTag") Bulk(c => c with { Tags = [.. c.Tags, BulkValue] }); else if (mode == "bulkDelete") { Companies.RemoveAll(c => Selected.Contains(c.Id)); Selected.Clear(); } else if (Active is not null) { var id = Active.Id; if (mode == "note" && Text.Length > 0) Update(id, c => c with { Notes = [.. c.Notes, Text] }); else if (mode == "task" && Text.Length > 0) Update(id, c => c with { Tasks = [.. c.Tasks, Text] }); else if (mode == "owner") Update(id, c => c with { Owner = BulkValue }); else if (mode == "archive") Update(id, c => c with { Status = "Archived" }); else if (mode == "delete") { Companies.RemoveAll(c => c.Id == id); Active = null; } else if (mode is not ("contact" or "deal")) return false; } else return false; Text = ""; return true; }
    public string Export(bool selected = false) { var rows = selected ? Companies.Where(c => Selected.Contains(c.Id)) : Filtered; return "Company,Domain,Industry,Owner,Pipeline,Status" + string.Concat(rows.Select(c => "\n" + string.Join(',', c.Name, c.Domain, c.Industry, c.Owner, c.Pipeline.ToString(CultureInfo.InvariantCulture), c.Status))); }
}
